"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs } from "./rs";
import { useFieldControl } from "./field";

export interface NativeSelectProps extends React.SelectHTMLAttributes<HTMLSelectElement> {
  label?: React.ReactNode;
}

const chevronLight =
  "url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' width='16' height='16' fill='none' stroke='%231A1A1A' stroke-width='1' stroke-linecap='butt' stroke-linejoin='miter'><g transform='rotate(90 8 8)'><path d='M5.5 3.5 L10.5 8 L5.5 12.5' vector-effect='non-scaling-stroke'/></g></svg>\")";
const chevronDark =
  "url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' width='16' height='16' fill='none' stroke='%23E8E8E8' stroke-width='1' stroke-linecap='butt' stroke-linejoin='miter'><g transform='rotate(90 8 8)'><path d='M5.5 3.5 L10.5 8 L5.5 12.5' vector-effect='non-scaling-stroke'/></g></svg>\")";

const styles = stylex.create({
  field: {
    width: "100%",
    display: "flex",
    flexDirection: "column",
    gap: "0.5rem",
  },
  label: {
    fontSize: {
      default: "0.75rem",
      [mq.phone]: raster.controlLabel,
    },
    fontWeight: 600,
    color: raster.gray,
    letterSpacing: "-0.01em",
    lineHeight: "16px",
  },
  select: {
    appearance: "none",
    WebkitAppearance: "none",
    boxSizing: "border-box",
    height: raster.controlH,
    minHeight: {
      default: null,
      [mq.phone]: raster.hit,
    },
    fontFamily: "inherit",
    fontSize: {
      default: "0.875rem",
      [mq.phone]: "1rem",
    },
    fontWeight: 500,
    letterSpacing: "-0.01em",
    lineHeight: `calc(${raster.controlH} - 2px)`,
    color: "var(--text)",
    caretColor: "var(--text)",
    backgroundColor: "var(--bg)",
    backgroundImage: {
      default: chevronLight,
      ':is([data-theme="dark"] *)': chevronDark,
    },
    backgroundRepeat: "no-repeat",
    backgroundPosition: "right 10px center",
    borderWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: {
      default: raster.controlBorder,
      ":focus": raster.accent,
    },
    borderRadius: {
      default: raster.radiusSm,
      [mq.phone]: 0,
    },
    paddingBlock: 0,
    paddingInlineStart: {
      default: "0.625rem",
      [mq.phone]: "0.875rem",
    },
    paddingInlineEnd: {
      default: "2rem",
      [mq.phone]: "2.25rem",
    },
    outlineWidth: {
      default: 0,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: "none",
      ":focus-visible": "solid",
    },
    outlineColor: raster.ink,
    outlineOffset: 2,
    width: "100%",
  },
  invalid: {
    borderColor: raster.ink,
  },
});

/** The platform list. Raster chrome. */
export const NativeSelect = React.forwardRef<HTMLSelectElement, NativeSelectProps>(
  function NativeSelect({ label, className, style, id, children, ...props }, ref) {
    const autoId = React.useId();
    const selectId = id ?? autoId;
    const field = useFieldControl(props);
    const invalid = field.invalid;
    const sx = rs(["rs-native-select", invalid && "rs-native-select-invalid", className], styles.select, invalid && styles.invalid);
    const control = (
      <select
        ref={ref}
        id={selectId}
        {...props}
        aria-describedby={field["aria-describedby"]}
        aria-invalid={field["aria-invalid"]}
        className={sx.className}
        style={{ ...sx.style, ...style }}
      >
        {children}
      </select>
    );
    if (label == null) return control;
    const stack = rs(["rs-field", "rs-native-select-field"], styles.field);
    const lab = rs(["rs-field-label", "rs-native-select-label"], styles.label);
    return (
      <div className={stack.className} style={stack.style}>
        <label className={lab.className} style={lab.style} htmlFor={selectId}>
          {label}
        </label>
        {control}
      </div>
    );
  },
);

/* ── native-select: generated from packages/react/src/components/native-select.tsx ── */
.rs-field.rs-native-select-field{width:100%;display:flex;flex-direction:column;gap:0.5rem}
.rs-field-label.rs-native-select-label{font-size:0.75rem;font-weight:600;color:var(--text-secondary);letter-spacing:-0.01em;line-height:16px}
@media (max-width: 640px){.rs-field-label.rs-native-select-label{font-size:var(--control-label)}}
.rs-native-select{appearance:none;-webkit-appearance:none;box-sizing:border-box;height:var(--control-h);font-family:inherit;font-size:0.875rem;font-weight:500;letter-spacing:-0.01em;line-height:calc(var(--control-h) - 2px);color:var(--text);caret-color:var(--text);background-color:var(--bg);background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' width='16' height='16' fill='none' stroke='%231A1A1A' stroke-width='1' stroke-linecap='butt' stroke-linejoin='miter'><g transform='rotate(90 8 8)'><path d='M5.5 3.5 L10.5 8 L5.5 12.5' vector-effect='non-scaling-stroke'/></g></svg>");background-repeat:no-repeat;background-position:right 10px center;border-width:1px;border-style:solid;border-color:var(--control-border);border-radius:var(--radius-sm);padding-block:0;padding-inline-start:0.625rem;padding-inline-end:2rem;outline-width:0;outline-style:none;outline-color:var(--text);outline-offset:2px;width:100%}
.rs-native-select:is([data-theme="dark"] *){background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' width='16' height='16' fill='none' stroke='%23E8E8E8' stroke-width='1' stroke-linecap='butt' stroke-linejoin='miter'><g transform='rotate(90 8 8)'><path d='M5.5 3.5 L10.5 8 L5.5 12.5' vector-effect='non-scaling-stroke'/></g></svg>")}
.rs-native-select:focus{border-color:var(--accent)}
.rs-native-select:focus-visible{outline-width:2px;outline-style:solid}
@media (max-width: 640px){.rs-native-select{min-height:var(--hit);font-size:1rem;border-radius:0;padding-inline-start:0.875rem;padding-inline-end:2.25rem}}
.rs-native-select-invalid{border-color:var(--text)}
